const PALACE_SRC = 'data:image/jpeg;base64,';
function loadImg(src) { const im = new Image(); im.src = src; return im; }
function photo(g, im, x, y, w, h, zoom, alpha) {   // cover-fit photo with slow Ken Burns zoom
  if (!im.complete || !im.naturalWidth) return; g.save(); g.globalAlpha = alpha; g.beginPath(); g.rect(x, y, w, h); g.clip();
  const r = Math.max(w / im.naturalWidth, h / im.naturalHeight) * zoom, iw = im.naturalWidth * r, ih = im.naturalHeight * r; g.drawImage(im, x + (w - iw) / 2, y + (h - ih) / 2, iw, ih); g.restore(); }
function credit(g, txt) { g.font = '600 20px Inter'; g.textAlign = 'right'; g.fillStyle = 'rgba(255,255,255,0.55)'; g.fillText(txt, W - 24, H * 0.205); }
const c = makeCanvas(), g = c.getContext('2d');
const PALACE = loadImg(PALACE_SRC);
window.renderFrame = function (t) { const k = clamp(t / DURATION);
  g.fillStyle = '#06080c'; g.fillRect(0, 0, W, H); photo(g, PALACE, 0, H * 0.14, W, H * 0.62, 1.15 + 0.08 * k, 1);
  const gr = g.createLinearGradient(0, H * 0.14, 0, H * 0.76); gr.addColorStop(0, 'rgba(6,8,12,0.65)'); gr.addColorStop(0.35, 'rgba(6,8,12,0.1)'); gr.addColorStop(1, 'rgba(6,8,12,0.95)'); g.fillStyle = gr; g.fillRect(0, H * 0.14, W, H * 0.62);
  g.fillStyle = '#06080c'; g.fillRect(0, H * 0.76, W, H); credit(g, "Photo: Adiraja / Wikimedia Commons, CC BY-SA 3.0"); SK.grain(g, t, 0.05); };